const {Driver} = require('../../gather/driver');
const {createMockSendCommandFn} = require('./driver-test');

async function testTimeoutScenario() {
  const connectionStub = {
    sendCommand: createMockSendCommandFn()
      .mockResponse('Page.navigate', {})
      .mockResponse('Runtime.evaluate', {result: {value: 2}}, 65000),
  };

  const driver = new Driver(connectionStub);
  driver.setNextProtocolTimeout(60000);

  try {
    await driver.evaluateAsync('1 + 1');
  } catch (err) {
    console.error('Error:', err);
  }
}

testTimeoutScenario();
